return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-10-02T10:29:43+00:00','po-revision-date'=>'2026-10-02T10:29:43+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'Objavljuje ovo web-mjesto na svakom jeziku koji odaberete, na vlastitim web-adresama, s prevedenim slugovima, metapodacima, izbornicima, WooCommerce proizvodima, hreflang-om, kartama web-mjesta za pojedine jezike i llms.txt. Prevodite sa svojim Zinn Digital® paketom ili vlastitim ključem pružatelja usluge.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Pohranjeno. Upišite novu vrijednost kako biste je zamijenili.','Filter this list…'=>'Filtrirajte ovaj popis…','Filter this list'=>'Filtrirajte ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Uklonite ovaj redak','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Copied'=>'Kopirano','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® priključak na ovoj web-stranici i radi li.','No connection is needed for this plugin.'=>'Za ovaj priključak nije potrebno povezivanje.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvezi postavke','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća sve postavke ovog priključka na njihove zadane vrijednosti. Želite li nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezite datoteku postavki','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve — morat ćete ih ponovno unijeti na novom web-mjestu.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke ovog priključka vraćene su na zadane vrijednosti.','Done.'=>'Dovršeno.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tu datoteku nije bilo moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® priključka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz postavki za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta datoteka je izvezena iz drugog priključka (%s), pa bi se njezinim uvozom ovdje spremile postavke koje ovaj priključak ne razumije.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d postavka je uvezena. Lozinke i API ključevi nikada nisu uključeni u izvoz, pa ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.','Translate'=>'Prevedi','Manual overrides'=>'Ručna poništenja','Sitemaps and URLs'=>'Mape web-mjesta i URL-ovi','General'=>'Općenito','Who pays for the translation'=>'Tko plaća prijevod','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'Ili Vaš Zinn Digital® plan, ili Vaš vlastiti API ključ. Nema besplatne razine — netko pružatelju usluge plaća svaku riječ.','My Zinn Digital® plan'=>'Moj Zinn Digital® paket','My own provider key'=>'Moj vlastiti ključ pružatelja usluga','Site ID'=>'ID web-mjesta','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'S vaše Zinn Digital® upravljačke ploče, na kartici Translation ove web-stranice.','Site token'=>'Token web-mjesta','An API key from your Zinn Digital® dashboard, on its API keys page. Give it the sites.view and sites.translation.manage permissions.'=>'API ključ s vaše Zinn Digital® nadzorne ploče, na njezinoj stranici API ključeva. Dodijelite mu dozvole sites.view i sites.translation.manage.','Provider'=>'Pružatelj usluge','API key'=>'API ključ','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'Vaš ključ, koji vam naplaćuje pružatelj usluge. Pohranjen je na ovoj web-stranici i šalje se samo njima.','Model'=>'Model','Leave empty for the cheapest model that does the job well.'=>'Ostavite prazno za najjeftiniji model koji dobro obavlja posao.','This site is written in'=>'Ovo web-mjesto napisano je na','Leave empty to use the site language from WordPress settings.'=>'Ostavite prazno kako biste koristili jezik web-mjesta iz postavki za WordPress.','Languages to publish'=>'Jezici za objavu','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'Svaki dobiva vlastite web adrese i vlastitu kartu web-mjesta. Objavite samo one jezike koje želite indeksirati.','Translate automatically when I publish or update'=>'Automatski prevedi kada objavim ili ažuriram','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'Uređivanjem stranice njezini se prijevodi označavaju kao zastarjeli te se ponovno izrađuju u pozadini. Uređivanje bez promjene ijedne riječi ništa ne košta.','What gets translated'=>'Što se prevodi','Post types'=>'Vrste objava','Translate the web addresses too'=>'Prevedite i web adrese','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'Francuski posjetitelji dobivaju /fr/a-propos/ umjesto /fr/about/. Neprevedena adresa nastavlja raditi i preusmjerava, pa se ništa što je indeksirano ne kvari.','Translate SEO titles, descriptions and image alt text'=>'Prevedite SEO naslove, opise i alternativni tekst slika','Translate categories and tags'=>'Prevedite kategorije i oznake','Translate navigation menus'=>'Prevedite navigacijske izbornike','Translate WooCommerce products and attributes'=>'Prevedite WooCommerce proizvode i atribute','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'Kratki opisi, bilješke o kupnji, oznake atributa i opisi varijacija. Cijene, SKU-ovi i pohranjene vrijednosti opcija nikada se ne mijenjaju.','SEO'=>'SEO','Add hreflang tags'=>'Dodaj hreflang oznake','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'Obavještava tražilice da su ove stranice ista stranica na različitim jezicima. Ostavite ovo uključeno osim ako to već ne čini drugi priključak.','Publish a sitemap for each language'=>'Objavite kartu web-mjesta za svaki jezik','Publish llms.txt for each language'=>'Objavite llms.txt za svaki jezik','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'Tekstualna karta web-mjesta koju čitaju AI tražilice s odgovorima. One često ne mogu izvršavati JavaScript i možda nikada neće dohvatiti kartu web-mjesta.','Language switcher'=>'Prebacivač jezika','Style'=>'Stil','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'Boje, razmaci i kutovi nalaze se na kartici Stil. Postavite ga pomoću bloka, kratkog koda [zinn_language_switcher] ili izbornika.','Show only these languages'=>'Prikaži samo ove jezike','Leave empty to show every language you publish.'=>'Ostavite prazno kako biste prikazali svaki jezik na kojem objavljujete.','Name each language in its own language'=>'Imenujte svaki jezik na njegovom vlastitom jeziku','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'Deutsch umjesto German. Netko tko ne može pročitati trenutnu stranicu ne može pročitati ni „German”.','Show flags'=>'Prikaži zastave','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'Zadano isključeno: jezik nije država, a arapski i španjolski nemaju jednu zastavu koja ne bi isključila većinu njihovih govornika.','Include the language being read'=>'Uključite jezik koji se čita','Include the original language'=>'Uključi izvorni jezik','Add it to this menu'=>'Dodajte ga u ovaj izbornik','Only the menu you name here. Nothing is added to any other menu on the site.'=>'Samo izbornik koji ovdje navedete. Ništa se ne dodaje ni u jedan drugi izbornik na web-mjestu.','Accent'=>'Naglasak','Background'=>'Pozadina','Text'=>'Tekst','Corner radius'=>'Polumjer kuta','Spacing'=>'Razmak','Text size'=>'Veličina teksta','Do not add it to a menu'=>'Nemojte ga dodavati u izbornik','none'=>'nijedno','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard, under "Shown to visitors". This site checks it every hour. Publishing now: %s.'=>'Na planu Zinn Digital® odabirete jezike za objavu na kartici Prijevod na nadzornoj ploči ovog web-mjesta, pod „Shown to visitors“. Ovo web-mjesto to provjerava svakih sat vremena. Sada se objavljuje: %s.','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard. This site has not read that choice yet, so it is still publishing: %s. Check the Site ID and token above.'=>'U sklopu paketa Zinn Digital® odabirete jezike za objavu na kartici Prijevod ove web-stranice na svojoj nadzornoj ploči. Ova stranica još nije očitala taj odabir pa i dalje objavljuje: %s. Provjerite ID stranice i token iznad.','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'Ovdje uredite bilo koji prijevod. Uređeni prijevod čuva se točno onako kako ste ga napisali i nikada se ne prepisuje kada se stranica ponovno prevodi.','Every language'=>'Svi jezici','Search translations'=>'Pretraži prijevode','Filter'=>'Filtriraj','Content'=>'Sadržaj','Language'=>'Jezik','Translation'=>'Prijevod','Status'=>'Status','Save'=>'Spremi','Nothing translated yet. Publish a language and translation starts in the background.'=>'Još ništa nije prevedeno. Objavite jezik i prevođenje će započeti u pozadini.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'Ove su adrese aktivne. Otvorite bilo koju od njih kako biste je provjerili i pošaljite indeks karte web-mjesta na Google Search Console.','You are not allowed to edit translations on this site.'=>'Nije vam dopušteno uređivati prijevode na ovom web-mjestu.','Edited by you — kept'=>'Uredili Vi — zadržano','Source changed — will be redone'=>'Izvor je promijenjen — ponovit će se','Up to date'=>'Ažurirano','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pozornost','Not connected'=>'Nije povezano','Running on your own account'=>'Pokretanje na vlastitom računu','We could not check this'=>'Nismo mogli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostički izvještaj i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Zadnja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Ovo je točno ono što će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu uključeni.','The diagnostics report that will be sent'=>'Dijagnostički izvještaj koji će biti poslan','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće podršci za Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo tiket podrške za Vas i odgovaramo e-poštom. Ako ga radije ne biste poslali, kopirajte ga iznad i sami zalijepite u tiket.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo uspjeli doći do Zinn Digital® s ovog poslužitelja (%s). Kopirajte gornje izvješće i umjesto toga otvorite tiket — u vašim postavkama nema nikakve pogreške.','Sent. Zinn® support has your report and will reply by email.'=>'Poslano. Zinn® podrška zaprimila je Vašu prijavu i odgovorit će Vam e-poštom.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Poslano. Podrška za Zinn® primila je Vašu prijavu — referenca %s — i odgovorit će Vam e-poštom.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko prijava u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno — prethodne su zaprimljene.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutačno nije mogao prihvatiti izvještaj — problem je s naše strane, a ne s Vaše. Pokušajte ponovno uskoro ili kopirajte gornji izvještaj u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga iznad i otvorite prijavu, navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® smještaj za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za osobe koje vode više od jedne web-stranice.','The Zinn® marketplace'=>'Tržnica Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web stranice, domene i postavljanja poveznica, pri čemu se novac sigurno čuva dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — unajmite ljude kojima je ovo zanimanje','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih stručnjaka: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im davanje ponuda.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'API ključ je odbijen. Provjerite je li još uvijek valjan i ima li pristup prijevodu, a zatim ga ponovno spremite.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'Pružatelj usluge je odbio zbog naplate ili kvote. Ništa nije prevedeno. Provjerite stanje i ograničenja na svojem računu kod njih.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'Pružatelj usluge prijevoda ima poteškoća na svojoj strani. Ništa nije prevedeno niti naplaćeno, a postupak će se ponovno pokušati u sljedećem prolazu.','The translation request failed and we could not tell why. Nothing was saved.'=>'Zahtjev za prijevod nije uspio i nismo mogli utvrditi zašto. Ništa nije spremljeno.','Sitemap index'=>'Indeks karte web-mjesta','%s sitemap'=>'%s mapa web-mjesta','LLM content map'=>'Karta sadržaja za LLM','%s LLM content map'=>'Karta LLM sadržaja za %s','Languages published'=>'Objavljeni jezici','Site language'=>'Jezik stranice','SEO plugin'=>'SEO priključak','No translation provider is set up yet.'=>'Još nije postavljen nijedan pružatelj usluga prevođenja.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'Zalijepite API ključ odabranog pružatelja usluga ili povežite web-mjesto s računom Zinn Digital® i prijevod će započeti u sljedećem prolazu.','Translating with your own %s key.'=>'Prevođenje s Vašim vlastitim %s ključem.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'Ovo web-mjesto nije povezano s računom za Zinn Digital®, što je u redu — vaš vam pružatelj usluga izravno ispostavlja račun.','Not connected to Zinn Digital® yet.'=>'Još nije povezano sa Zinn Digital®.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'Dodajte ID i token ove web-lokacije sa svoje nadzorne ploče za Zinn Digital® ili se prebacite na vlastiti ključ pružatelja usluge kako biste radili bez računa.','Connected to Zinn Digital®.'=>'Povezano sa Zinn Digital®.','The translation provider is having a problem.'=>'Pružatelj usluga prevođenja ima problem.','Translation is paused — your provider needs attention.'=>'Prijevod je pauziran — vaš pružatelj usluge zahtijeva pažnju.','Translation has not been set up yet.'=>'Prijevod još nije postavljen.','Something went wrong at our end.'=>'Došlo je do pogreške s naše strane.','Check their status page'=>'Provjerite njihovu stranicu statusa','Fix this on your account'=>'Ispravite ovo na svojem računu','Style preset'=>'Zadana postavka stila','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod je nadjačava.','Use my own colours and sizes'=>'Koristite moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i predlošak će se koristiti točno onakav kakav jest.','Zinn® language switcher'=>'Prebacivač jezika za Zinn®','Let visitors read this page in another language.'=>'Dopustite posjetiteljima čitanje ove stranice na drugom jeziku.','Title'=>'Naslov','Use the plugin setting'=>'Upotrijebite postavku priključka','Dropdown'=>'Padajući izbornik','Inline list'=>'Ugrađeni popis','Pills'=>'Pilule','Minimal text'=>'Minimalni tekst','Flags and names'=>'Zastave i nazivi','Stacked list'=>'Složeni popis','Choose a language'=>'Odaberite jezik','See the Zinn Digital® release notes.'=>'Pogledajte napomene o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije pružila poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ova web-stranica pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti sa Zinn® usluge ažuriranja (%s). Pokušajte ponovo za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','No DeepL API key is saved, so there is nothing to translate with.'=>'Nije spremljen nijedan DeepL API ključ, pa se nema čime prevoditi.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL ne prevodi na %s. Odaberite Google Gemini ili OpenAI za ovaj jezik ili povežite web-mjesto sa Zinn Digital®.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije bilo moguće stupiti u vezu s uslugom DeepL. Ništa nije prevedeno i ništa nije naplaćeno; ponovno će se pokušati u sljedećem prolazu.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'Vaša DeepL kvota znakova za ovo razdoblje je potrošena. Prijevod će se nastaviti kada se poništi ili kada povećate ograničenje na svom DeepL računu.','DeepL answered with something we could not read. Nothing was saved.'=>'DeepL je odgovorio nečim što nismo mogli pročitati. Ništa nije spremljeno.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Nije spremljen nijedan Google Gemini API ključ, pa se nema čime prevoditi.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije se moglo povezati s uslugom Google Gemini. Ništa nije prevedeno i ništa nije naplaćeno; pokušat će se ponovno u sljedećem prolazu.','No OpenAI API key is saved, so there is nothing to translate with.'=>'Nije spremljen OpenAI API ključ, pa se nema čime prevoditi.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Nije bilo moguće uspostaviti vezu s OpenAI-jem. Ništa nije prevedeno i ništa nije naplaćeno; pokušat će se ponovo u sljedećem prolazu.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'Ovo web-mjesto nije povezano sa Zinn Digital®, stoga nema ničega za prikupljanje. Dodajte ID web-mjesta i token ili se prebacite na vlastiti ključ pružatelja usluge.','This site is not connected to Zinn Digital®.'=>'Ovo web-mjesto nije povezano sa Zinn Digital®.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'Nije bilo moguće uspostaviti vezu sa Zinn Digital®. Ništa nije poslano; pokušat će se ponovno u sljedećem prolazu.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'Prijevod je pauziran na ovom web-mjestu. Provjerite je li račun ažuriran na vašoj Zinn Digital® upravljačkoj ploči.','Zinn Digital® rejected this site\'s token. It must be an API key with the sites.view and sites.translation.manage permissions — create one on the API keys page of your dashboard.'=>'Zinn Digital® je odbio token ove web-stranice. To mora biti API ključ s dozvolama sites.view i sites.translation.manage — stvorite ga na stranici API ključeva na svojoj upravljačkoj ploči.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'Nije moguće uspostaviti vezu sa Zinn Digital®. Vaša web-stranica nastavlja posluživati prijevode koje već ima.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Zinn Digital® je odgovorio nečim što nismo mogli pročitati. Vaše web-mjesto nastavlja posluživati prijevode koje već ima.','Zinn Digital® could not be reached. Your site keeps publishing the languages it already has.'=>'Nije se moglo uspostaviti vezu sa Zinn Digital®. Vaša web-stranica nastavlja objavljivati jezike koje već ima.','Zinn Digital® answered with something we could not read. Your site keeps publishing the languages it already has.'=>'Zinn Digital® je odgovorio nečim što nismo mogli pročitati. Vaše web-mjesto nastavlja objavljivati jezike koje već ima.']];